def search(self, cr, uid, args, offset=0, limit=0, order=None, context=None, count=False):
        new_args = []
        for arg in args:
            if arg[0] == 'year':
                new_args.append(('date', '>=', '{year}-01-01'.format(year=arg[2])))
                new_args.append(('date', '<=', '{year}-12-31'.format(year=arg[2])))
            else:
                new_args.append(arg)

        return super(account_bank_statement, self).search(cr, uid, new_args, offset=offset, limit=limit, order=order, context=context, count=count)

def onchange_partner_id(self, cr, uid, ids, i_type, partner_id, date_invoice=False, payment_term=False, bank_riba_id=False, company_id=False, context=None):
        result = super(account_invoice, self).onchange_partner_id(
            cr, uid, ids, i_type, partner_id, date_invoice, payment_term, bank_riba_id, company_id)

        partner = self.pool['res.partner'].browse(cr, uid, partner_id, context)
        if partner.bank_riba_id:
            result['value']['bank_riba_id'] = partner.bank_riba_id.id
        if partner.company_bank_id:
            result['value']['partner_bank_id'] = partner.company_bank_id.id

        return result

def create(self, cr, uid, vals, context=None):
        recompute_obj = self.pool.get('account.asset.recompute.trigger')
        recompute_vals = {
            'reason': 'creation of fiscalyear %s' % vals.get('code'),
            'company_id': vals.get('company_id') or self.pool.get('res.users').browse(cr, uid, uid, context).company_id.id,
            'date_trigger': time.strftime(tools.DEFAULT_SERVER_DATETIME_FORMAT),
            'state': 'open',
        }
        recompute_obj.create(cr, SUPERUSER_ID, recompute_vals, context=context)
        return super(account_fiscalyear, self).create(cr, uid, vals, context=context)

